function maxDiff(num) {
  const digits = String(num);

  let high = digits;
  for (const digit of digits) {
    if (digit !== "9") {
      high = digits.replaceAll(digit, "9");
      break;
    }
  }

  let low = digits;
  if (digits[0] !== "1") {
    low = digits.replaceAll(digits[0], "1");
  } else {
    for (let i = 1; i < digits.length; i++) {
      if (digits[i] !== "0" && digits[i] !== "1") {
        low = digits.replaceAll(digits[i], "0");
        break;
      }
    }
  }
  return Number(high) - Number(low);
}

