function maxDiff(num) {
  const text = "" + num;
  let biggest = -Infinity;
  let smallest = Infinity;
  for (let x = 0; x <= 9; x++) {
    for (let y = 0; y <= 9; y++) {
      let changed = "";
      for (const ch of text) changed += ch === String(x) ? String(y) : ch;
      if (changed[0] === "0") continue;
      const value = parseInt(changed, 10);
      if (value === 0) continue;
      biggest = Math.max(biggest, value);
      smallest = Math.min(smallest, value);
    }
  }
  return biggest - smallest;
}

