function generate(rand, size) {
  if (rand() < 0.1) return [100000000];
  const len = size === 'large' ? 8 : 1 + Math.floor(rand() * 8);
  const alphabet = [];
  const kinds = 1 + Math.floor(rand() * 4);
  const pool = ["0", "1", "9", String(Math.floor(rand() * 10))];
  for (let k = 0; k < kinds; k++) alphabet.push(rand() < 0.6 ? pool[Math.floor(rand() * pool.length)] : String(Math.floor(rand() * 10)));
  let text = String(1 + Math.floor(rand() * 9));
  if (rand() < 0.4) text = rand() < 0.5 ? "1" : "9";
  while (text.length < len) text += alphabet[Math.floor(rand() * alphabet.length)];
  return [Number(text)];
}
